"""FIXED harness: the process the candidate draft controller runs in (unprivileged, CPU only).

Imports the candidate's ``draft_policy.py``, calls ``calibrate()`` once and then
answers the decoder's per-round questions over two FIFOs.  The candidate's own
prints are redirected to stderr so they cannot corrupt the protocol.  This
process never holds the model or the prompts; it sees, per prompt, the last
positions of the prompt and every generated token, the draft distributions and
the per-layer "shadow" predictions at the verified positions.

Calls made by the decoder (all inside one persistent process):
  begin(prompt, state)       a new prompt (prefill shadow of its last positions)
  plan(state, ops)           the next round's draft: exit layer or sublayer mask,
                             max draft length, stop feedback on/off, tree on/off;
                             ``ops`` (probe / apply / states / head) may be used
                             here and only here -- every probe and apply is
                             metered in the cost
  step(feat, state)          after each draft token when feedback is on: keep
                             drafting?
  tree(steps, state)         when tree is on: the token tree to verify
  observe(result, state)     the verification outcome
``calibrate`` receives ``simulate(state)``: each call runs the real
self-speculative decoder on a few calibration prompts with this controller and
returns the realised eTPL.  At most ``cal["max_simulations"]`` calls.
"""
import importlib.util
import json
import os
import struct
import sys

import numpy as np

_IN = open(os.environ["MLSEE_FIFO_IN"], "rb", buffering=0)
_PROTO_OUT = os.open(os.environ["MLSEE_FIFO_OUT"], os.O_WRONLY)
os.dup2(2, 1)
sys.stdout = sys.stderr
_ALLOWED = {"bool", "uint8", "int32", "int64", "float16", "float32", "float64"}


def _read_exact(n):
    buf = bytearray()
    while len(buf) < n:
        chunk = _IN.read(min(n - len(buf), 1 << 20))
        if not chunk:
            return None
        buf.extend(chunk)
    return bytes(buf)


def _read_frame():
    hdr = _read_exact(8)
    if hdr is None:
        return None, None
    (hl,) = struct.unpack("<Q", hdr)
    meta = json.loads(_read_exact(hl))
    arrays = {}
    for name, dt, shape in meta.get("a", []):
        if dt not in _ALLOWED:
            raise ValueError("unexpected dtype %r" % dt)
        dt = np.dtype(dt)
        n = int(np.prod(shape)) * dt.itemsize
        arrays[name] = np.frombuffer(_read_exact(n), dtype=dt).reshape(shape).copy()
    return meta["h"], arrays


def _write_frame(header, arrays=None):
    arrays = arrays or {}
    names = sorted(arrays)
    meta = {"h": header, "a": [[n, str(arrays[n].dtype), list(arrays[n].shape)] for n in names]}
    hb = json.dumps(meta).encode()
    data = b"".join([struct.pack("<Q", len(hb)), hb]
                    + [np.ascontiguousarray(arrays[n]).tobytes() for n in names])
    view = memoryview(data)
    while view:
        k = os.write(_PROTO_OUT, view)
        view = view[k:]


class Ops:
    """Metered model services, usable inside ``plan`` only."""

    def __init__(self, n_layers, d):
        self.open = False
        self.L, self.d = n_layers, d

    def _call(self, header, arrays, want):
        if not self.open:
            raise RuntimeError("ops may only be used inside plan()")
        _write_frame(header, arrays)
        h, a = _read_frame()
        if h is None or h.get("type") != want:
            raise RuntimeError("unexpected reply %r to %s" % (None if h is None else h.get("type"),
                                                               header["type"]))
        return a

    def probe(self, mask, i0, i1):
        """Draft with sublayer mask over generated tokens [i0, i1) of this prompt
        (teacher-forced, attending to the committed cache before them).  Returns
        top_val/top_id/lse per position (the draft's prediction of the NEXT token).
        Costs the kept sublayers once."""
        m = np.asarray(mask).astype(np.uint8).reshape(-1)
        return self._call({"type": "probe", "i0": int(i0), "i1": int(i1)}, {"mask": m},
                          "probe_result")

    def apply(self, block, x, n):
        """Apply sublayer ``block`` (2l = layer l's attention, 2l+1 its MLP) to x
        (nb, n, d): nb branches, each a copy of the LAST n committed positions.
        Costs that sublayer once."""
        x = np.asarray(x, dtype=np.float16)
        return self._call({"type": "apply", "block": int(block), "n": int(n)}, {"x": x},
                          "apply_result")["y"]

    def states(self, n):
        """The 2L+1 sublayer-boundary states (2L+1, n, d) of the last n committed
        tokens (requires keep_states in an earlier plan).  Free."""
        return self._call({"type": "states", "n": int(n)}, None, "states_result")["x"]

    def head(self, x):
        """Final norm + LM head on states x (m, d): top_val/top_id/lse.  Free."""
        return self._call({"type": "head"}, {"x": np.asarray(x, dtype=np.float16)}, "head_result")


def main():
    spec = importlib.util.spec_from_file_location("draft_policy", sys.argv[1])
    rule = importlib.util.module_from_spec(spec)
    spec.loader.exec_module(rule)
    n_layers = int(os.environ["MLSEE_LAYERS"])
    seed = int(os.environ["MLSEE_SEED"])
    with np.load(os.environ["MLSEE_CAL"], allow_pickle=False) as z:
        cal = {k: z[k] for k in z.files}
    max_sims = int(cal["max_simulations"])
    ops = Ops(n_layers, int(cal["hidden_size"]))
    end_hook = getattr(rule, "end", None)

    def serve(h, a, state):
        t = h["type"]
        if t == "begin":
            prompt = dict(a)
            prompt["seq"] = int(h["seq"])
            prompt["prompt_len"] = int(h["prompt_len"])
            rule.begin(prompt, state)
        elif t == "plan":
            ops.open = True
            try:
                p = rule.plan(state, ops)
            finally:
                ops.open = False
            if not isinstance(p, dict):
                raise TypeError("plan() must return a dict")
            hdr = {"type": "ans", "max_draft": int(p.get("max_draft", 0)),
                   "feedback": bool(p.get("feedback", False)), "tree": bool(p.get("tree", False)),
                   "keep_states": bool(p.get("keep_states", False))}
            arr = {}
            if p.get("mask") is not None:
                arr["mask"] = np.asarray(p["mask"]).astype(np.uint8).reshape(-1)
            else:
                hdr["exit"] = int(p["exit"])
            _write_frame(hdr, arr)
        elif t == "step":
            cont = bool(rule.step(dict(a, i=int(h["i"])), state))
            _write_frame({"type": "ans", "cont": cont})
        elif t == "tree":
            par, tok = rule.tree(dict(a), state)
            _write_frame({"type": "ans"}, {"parent": np.asarray(par, dtype=np.int64).reshape(-1),
                                           "token": np.asarray(tok, dtype=np.int64).reshape(-1)})
        elif t == "result":
            res = dict(a)
            res["accepted"] = int(h["accepted"])
            res["n_draft"] = int(h["n_draft"])
            res["tree"] = bool(h["tree"])
            rule.observe(res, state)
        elif t == "end":
            if end_hook is not None:
                end_hook(state)
        else:
            raise RuntimeError("unexpected frame %r" % t)

    used = [0]

    def simulate(state):
        if used[0] >= max_sims:
            raise RuntimeError("simulate() may be called at most %d times" % max_sims)
        used[0] += 1
        _write_frame({"type": "sim"})
        while True:
            h, a = _read_frame()
            if h is None:
                raise EOFError("decoder closed the pipe during a simulation")
            if h["type"] == "sim_result":
                if "error" in h:
                    raise RuntimeError(h["error"])
                out = {k: h[k] for k in ("etpl", "acceptance", "n_tokens", "rounds")}
                out.update(a)
                return out
            serve(h, a, state)

    state = rule.calibrate(cal, n_layers, seed, simulate)
    if not isinstance(state, dict):
        raise TypeError("calibrate() must return a dict")
    _write_frame({"type": "ready"})
    while True:
        h, a = _read_frame()
        if h is None or h["type"] == "finish":
            return
        serve(h, a, state)


if __name__ == "__main__":
    main()

